Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
import java.io.*;
import java.util.regex.*;

public class Text_Document_Analysis {
	public static void main(String args[]) throws Exception {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		f.readLine();
		String temp = f.readLine();

		Pattern p = Pattern.compile("\\([a-zA-Z_]*\\)");
		String[] outside = p.split(temp);
		int one = 0;
		for (String segment : outside) {
			for (String word : segment.split("_+")) {
				if (word.length() > one)
					one = word.length();
			}
		}

		int two = 0;
		boolean inside = false;
		boolean inWord = false;
		for (int i = 0; i < temp.length(); i++) {
			char c = temp.charAt(i);
			if (c == '(')
				inside = true;
			if (c == ')') {
				inWord = false;
				inside = false;
			}
			if (inside && isLetter(c)) {
				if (!inWord) {
					two++;
					inWord = true;
				}
			}
			if (c == '_')
				inWord = false;
		}
		System.out.println(one + " " + two);
	}

	private static boolean isLetter(char c) {
		return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
	}
}
